variants = [
    ('01', 'Danh sách & chi tiết', common + '.hero{min-height:260px}.hero img{max-height:220px}.app{grid-template-columns:74px 455px minmax(0,1fr)}.details{margin-top:4px;margin-bottom:20px}.facts{margin-bottom:24px;padding:16px 0}.timeline .event{min-height:52px}.data-row{min-height:52px}', ''),
    ('02', 'Bảng tồn kho & chi tiết', common + compact, tablejs.replace('ROW', table_row)),
    ('03', 'Lưới xe & chi tiết', common + compact + gridcss, tablejs.replace('ROW', grid_row) + "document.querySelector('.table-head').remove();"),
]
for number,title,css,js in variants:
    html=base.replace('</style>',css+'</style>').replace('</body>', '<script>'+js+'</script></body>')
    html=html.replace('Kho xe · Mẫu giao diện','Kho xe · Mẫu '+number+' · '+title)
    html=html.replace('MẪU XEM TRƯỚC · 29/10/2026','MẪU '+number+' · '+title.upper())
    target=root/('public/previews/kho-xe-mau-'+number+'.html')
    target.write_text(html,encoding='utf-8')
    print(target.name)
